const fs = await import('node:fs');
const path = globalThis.input_path;
if (!fs.existsSync(path)) {
  throw new Error('Input file not found: ' + path);
}
const buffer = fs.readFileSync(path);
globalThis.inputBuffer = buffer;
globalThis.output_path = globalThis.output_path;

const mod = await import('office-to-pdf');
const toPdf = mod.default || mod;
const pdfBuffer = await toPdf(globalThis.inputBuffer);
globalThis.pdfBuffer = pdfBuffer;

const fs = await import('node:fs');
const outPath = globalThis.output_path;
fs.writeFileSync(outPath, globalThis.pdfBuffer);
const size = fs.statSync(outPath).size;
console.log(JSON.stringify({ output_path: outPath, size_bytes: size }));
